//! The desktop's icons as data: which there are (`Icon`) and their drawings as outlines on the 24 grid (`drawn`), lucide's
//! and Arqiflow's own, generated by tools/icons/generate.mjs. A crate of its own so the 0.6 MB of generated outlines, which
//! almost never change, are not rebuilt with the interface; `bimcraft-ui-egui`'s `icons` draws them with the one pen.

#[rustfmt::skip]
mod drawn;
pub use drawn::{Drawn, LUCIDE_VERSION, Origin, drawn};

macro_rules! icon_names {
    ($($name:ident),* $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
        pub enum Icon { $($name),* }
        impl Icon {
            pub const ALL: &'static [Self] = &[$(Self::$name),*];
            pub const fn name(self) -> &'static str {
                match self { $(Self::$name => stringify!($name)),* }
            }
        }
    };
}

